const listEligibleSkillEvolutionLoops = `-- name: ListEligibleSkillEvolutionLoops :many
SELECT id, workspace_id, skill_id, mode, cooldown_seconds, minimum_signals, max_evidence_refs, max_replay_samples, max_cost_usd_ticks, policy_version, last_observed_at, last_proposal_at, next_eligible_at, created_at, updated_at, is_enabled FROM skill_evolution_loop
WHERE is_enabled
  AND mode = 'propose'
  AND (next_eligible_at IS NULL OR next_eligible_at <= $1::timestamptz)
  AND ($2::uuid IS NULL OR id > $2::uuid)
ORDER BY id
LIMIT $3
`

type ListEligibleSkillEvolutionLoopsParams struct {
	EligibleAt pgtype.Timestamptz `json:"eligible_at"`
	AfterID    pgtype.UUID        `json:"after_id"`
	PageSize   int32              `json:"page_size"`
}

func (q *Queries) ListEligibleSkillEvolutionLoops(ctx context.Context, arg ListEligibleSkillEvolutionLoopsParams) ([]SkillEvolutionLoop, error) {
	rows, err := q.db.Query(ctx, listEligibleSkillEvolutionLoops, arg.EligibleAt, arg.AfterID, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SkillEvolutionLoop{}
	for rows.Next() {
		var i SkillEvolutionLoop
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.SkillID,
			&i.Mode,
			&i.CooldownSeconds,
			&i.MinimumSignals,
			&i.MaxEvidenceRefs,
			&i.MaxReplaySamples,
			&i.MaxCostUsdTicks,
			&i.PolicyVersion,
			&i.LastObservedAt,
			&i.LastProposalAt,
			&i.NextEligibleAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.IsEnabled,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

